[] a owl:AllDisjointClasses ;
    owl:members (
        ht:BloodPressureReading
        ht:Hypertension
        ht:Antihypertensive
        ht:SecondaryCause
        ht:TargetOrganDamage
        ht:RiskFactor
        ht:BloodPressureMeasurementMethod
        ht:RetinopathyFinding
    ) .
